#[test]
fn every_fixture_payload_deserialises_into_its_generated_type() {
    let logs = fixture_logs();
    assert!(logs.len() > 20, "expected the 1.2 fixtures next to this workspace, found {}", logs.len());
    let mut seen = std::collections::BTreeMap::<String, usize>::new();
    let mut rejected = Vec::new();
    for log in &logs {
        let text = std::fs::read_to_string(log).unwrap();
        for (i, line) in text.lines().enumerate() {
            let Ok(serde_json::Value::Object(ev)) = serde_json::from_str::<serde_json::Value>(line.trim()) else {
                continue; // corrupt lines are the fold's business, not the schema's
            };
            let (Some(kind), Some(payload)) = (ev.get("type").and_then(|t| t.as_str()), ev.get("payload")) else {
                continue;
            };
            if !payload.is_object() {
                continue; // syn.corrupt carries a non-object payload on purpose
            }
            match accepts(kind, payload) {
                None => {}
                Some(Ok(())) => *seen.entry(kind.to_owned()).or_default() += 1,
                Some(Err(e)) => {
                    // The synthetic `corrupt` record deliberately carries
                    // payloads the validators reject (a task_status_changed with
                    // no id); the generated types reject those too. Anything
                    // else is a generated type narrower than the TypeScript one.
                    if !log.to_string_lossy().contains("/synthetic/corrupt/") {
                        rejected.push(format!("{}:{}: {kind}: {e}", log.display(), i + 1));
